package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class JsonWriter_nullValue_TriageGen1Test {

    @Test
    public void testNullValue_NoDeferredName() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        // Ensure no deferred name exists by calling a method that clears it or starting fresh
        // In JsonWriter, name() sets deferredName.

        JsonWriter result = writer.nullValue();

        assertEquals("null", sw.toString());
        assertSame(writer, result);
    }

    @Test
    public void testNullValue_WithDeferredName_AndSerializeNullsTrue() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);
        writer.setSerializeNulls(true);

        // Set a deferred name
        writer.name("testKey");

        // Call nullValue()
        JsonWriter result = writer.nullValue();

        // Expected output: {"testKey":null}
        // Note: name() doesn't write to out immediately, writeDeferredName() does.
        assertEquals("{\"testKey\":null}", sw.toString());
        assertSame(writer, result);
    }

    @Test
    public void testNullValue_WithDeferredName_AndSerializeNullsFalse() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);
        writer.setSerializeNulls(false);

        // Set a deferred name
        writer.name("testKey");

        // Call nullValue()
        JsonWriter result = writer.nullValue();

        // Since serializeNulls is false, it should skip the name and the value.
        // The output should be empty because the name was deferred and now discarded.
        assertEquals("", sw.toString());
        assertSame(writer, result);
    }

    @Test
    public void testNullValue_SequentialUsage() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        writer.beginObject();
        writer.name("a");
        writer.nullValue();
        writer.name("b");
        writer.value("val");
        writer.endObject();

        assertEquals("{\"a\":null,\"b\":\"val\"}", sw.toString());
    }
}
